import heapq
from typing import List

def farthestSeatAssignment(n: int, count: int) -> List[int]:
    res = []
    if n <= 0 or count <= 0:
        return res
    res.append(0)
    if n >= 2 and count >= 2:
        res.append(n - 1)
    # 堆里放空段 (-离最近已坐座位的距离, 左端, 右端)，左右端都已坐人
    heap = []
    def push(l, r):
        if r - l > 1:
            heapq.heappush(heap, (-((r - l) // 2), l, r))
    if len(res) == 2:
        push(0, n - 1)
    while len(res) < count and heap:
        _, l, r = heapq.heappop(heap)
        mid = (l + r) // 2          # 偶数长度取靠左的中点
        res.append(mid)
        push(l, mid)
        push(mid, r)
    return res

class Solution {
    int[] farthestSeatAssignment(int n, int count) {
        if (count == 0) return new int[0];
        java.util.List<Integer> res = new java.util.ArrayList<>();
        res.add(0);
        if (count == 1 || n == 1) return res.stream().mapToInt(Integer::intValue).toArray();
        res.add(n - 1);
        if (count == 2 || n == 2) return res.stream().mapToInt(Integer::intValue).toArray();
        java.util.PriorityQueue<int[]> heap = new java.util.PriorityQueue<>((a, b) -> {
            int dA = (a[1] - a[0]) / 2, dB = (b[1] - b[0]) / 2;
            if (dA != dB) return Integer.compare(dB, dA);
            return Integer.compare(a[0], b[0]);
        });
        if (n - 1 > 1) heap.add(new int[]{0, n - 1});
        while (res.size() < count && !heap.isEmpty()) {
            int[] s = heap.poll();
            int l = s[0], r = s[1];
            int mid = l + (r - l) / 2;
            res.add(mid);
            if (mid - l > 1) heap.add(new int[]{l, mid});
            if (r - mid > 1) heap.add(new int[]{mid, r});
        }
        return res.stream().mapToInt(Integer::intValue).toArray();
    }
}

class Solution {
public:
    vector<int> farthestSeatAssignment(int n, int count) {
        if (count == 0) return {};
        vector<int> res = {0};
        if (count == 1 || n == 1) return res;
        res.push_back(n - 1);
        if (count == 2 || n == 2) return res;
        auto cmp = [](const pair<int,int>& a, const pair<int,int>& b) {
            int dA = (a.second - a.first) / 2, dB = (b.second - b.first) / 2;
            if (dA != dB) return dA < dB;
            return a.first > b.first;
        };
        priority_queue<pair<int,int>, vector<pair<int,int>>, decltype(cmp)> heap(cmp);
        if (n - 1 > 1) heap.push({0, n - 1});
        while ((int)res.size() < count && !heap.empty()) {
            auto [l, r] = heap.top(); heap.pop();
            int mid = l + (r - l) / 2;
            res.push_back(mid);
            if (mid - l > 1) heap.push({l, mid});
            if (r - mid > 1) heap.push({mid, r});
        }
        return res;
    }
};
